            ticker: deque(maxlen=4)
            for ticker in self.symbols
        }
        self.previous_spy_close = None
        self.previous_spy_average = None

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bar = data.Bars[symbol]
                bars[ticker] = bar
                self.closes[ticker].append(float(bar.Close))

                if ticker == "SPY":
                    self.spy_average.Update(bar.EndTime, bar.Close)
                elif ticker == "AAPL":
                    self.aapl_rsi.Update(bar.EndTime, bar.Close)

        complete_day = len(bars) == len(self.symbols)

        if complete_day and self._all_state_ready():
            self._evaluate_sells(bars)
            self._evaluate_buys(bars)

        if "SPY" in bars and self.spy_average.IsReady:
            self.previous_spy_close = float(bars["SPY"].Close)
            self.previous_spy_average = float(self.spy_average.Current.Value)

    def _all_state_ready(self):
        return (
            self.spy_average.IsReady
            and self.aapl_rsi.IsReady
            and self.previous_spy_close is not None
            and self.previous_spy_average is not None
            and len(self.closes["AAPL"]) == 4
        )

    def _evaluate_sells(self, bars):
        spy_close = float(bars["SPY"].Close)
        spy_average = float(self.spy_average.Current.Value)
        spy_crosses_below = (
            self.previous_spy_close >= self.previous_spy_average
            and spy_close < spy_average
        )
        if self.spy_lot > 0 and spy_crosses_below:
            self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and float(self.aapl_rsi.Current.Value) > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

    def _evaluate_buys(self, bars):
        spy_close = float(bars["SPY"].Close)
        spy_average = float(self.spy_average.Current.Value)
        spy_crosses_above = (
            self.previous_spy_close <= self.previous_spy_average
            and spy_close > spy_average
        )
        if self.spy_lot == 0 and spy_crosses_above:
            quantity = floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / spy_close)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        aapl_closes = self.closes["AAPL"]
        three_red_days = all(
            aapl_closes[index] < aapl_closes[index - 1]
            for index in range(1, 4)
        )
        if self.aapl_lot == 0 and three_red_days:
            cash_required = 20_000
            if float(self.Portfolio.Cash) >= cash_required:
                quantity = floor(cash_required / float(bars["AAPL"].Close))
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

