class ParallelSpyAaplStrategies(QCAlgorithm):
    SPY_MOVING_AVERAGE_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=self.SPY_MOVING_AVERAGE_PERIOD + 1)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.rsi_previous_close = None
        self.rsi_change_count = 0
        self.rsi_seed_gains = 0.0
        self.rsi_seed_losses = 0.0
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.lots = {"A": 0, "B": 0}
        self.pending = {"A": False, "B": False}
        self.order_owners = {}

    def OnData(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(spy):
            self.spy_closes.append(float(data.Bars[spy].Close))

        if data.Bars.ContainsKey(aapl):
            aapl_close = float(data.Bars[aapl].Close)
            self._update_aapl_red_streak(aapl_close)
            self._update_aapl_rsi(aapl_close)

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        spy_close = float(data.Bars[spy].Close)
        aapl_close = float(data.Bars[aapl].Close)

        spy_ready = len(self.spy_closes) == self.spy_closes.maxlen
        rsi_ready = self.aapl_rsi is not None
        if not (spy_ready and rsi_ready):
            return

        # All independent strategy sells are evaluated before any buys.
        if self.lots["A"] > 0 and not self.pending["A"]:
            yesterday_close = self.spy_closes[-2]
            today_close = self.spy_closes[-1]
            yesterday_average = sum(list(self.spy_closes)[:-1]) / self.SPY_MOVING_AVERAGE_PERIOD
            today_average = sum(list(self.spy_closes)[1:]) / self.SPY_MOVING_AVERAGE_PERIOD
            if yesterday_close >= yesterday_average and today_close < today_average:
                self._submit_order("A", spy, -self.lots["A"])

        if self.lots["B"] > 0 and not self.pending["B"]:
            if self.aapl_rsi > 60:
                self._submit_order("B", aapl, -self.lots["B"])

        if self.lots["A"] == 0 and not self.pending["A"]:
            yesterday_close = self.spy_closes[-2]
            today_close = self.spy_closes[-1]
            yesterday_average = sum(list(self.spy_closes)[:-1]) / self.SPY_MOVING_AVERAGE_PERIOD
            today_average = sum(list(self.spy_closes)[1:]) / self.SPY_MOVING_AVERAGE_PERIOD
            if yesterday_close <= yesterday_average and today_close > today_average:
                quantity = self.CalculateOrderQuantity(spy, 0.40)
                if quantity > 0:
                    self._submit_order("A", spy, quantity)

        if self.lots["B"] == 0 and not self.pending["B"]:
            if self.aapl_red_streak >= 3 and float(self.Portfolio.Cash) >= 20_000:
                quantity = floor(20_000 / aapl_close)
                if quantity > 0:
                    self._submit_order("B", aapl, quantity)

    def _update_aapl_red_streak(self, close):
        if self.aapl_previous_close is not None:
            if close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
        self.aapl_previous_close = close

    def _update_aapl_rsi(self, close):
        if self.rsi_previous_close is None:
            self.rsi_previous_close = close
            return

        change = close - self.rsi_previous_close
        gain = max(change, 0.0)
        loss = max(-change, 0.0)
        self.rsi_change_count += 1

        if self.rsi_change_count <= self.RSI_PERIOD:
            self.rsi_seed_gains += gain
            self.rsi_seed_losses += loss
            if self.rsi_change_count == self.RSI_PERIOD:
                self.rsi_average_gain = self.rsi_seed_gains / self.RSI_PERIOD
                self.rsi_average_loss = self.rsi_seed_losses / self.RSI_PERIOD
        else:
            self.rsi_average_gain = (
                self.rsi_average_gain * (self.RSI_PERIOD - 1) + gain
            ) / self.RSI_PERIOD
            self.rsi_average_loss = (
                self.rsi_average_loss * (self.RSI_PERIOD - 1) + loss
            ) / self.RSI_PERIOD

        if self.rsi_average_gain is not None:
            if self.rsi_average_loss == 0:
                self.aapl_rsi = 100.0 if self.rsi_average_gain > 0 else 0.0
            else:
                relative_strength = self.rsi_average_gain / self.rsi_average_loss
                self.aapl_rsi = 100.0 - 100.0 / (1.0 + relative_strength)

        self.rsi_previous_close = close

    def _submit_order(self, owner, symbol, quantity):
        ticket = self.MarketOrder(symbol, quantity)
        self.pending[owner] = True
        self.order_owners[ticket.OrderId] = owner

    def OnOrderEvent(self, order_event):
        owner = self.order_owners.get(order_event.OrderId)
        if owner is None:
            return

        fill_quantity = int(order_event.FillQuantity)
        if fill_quantity != 0:
            self.lots[owner] = max(0, self.lots[owner] + fill_quantity)

        if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            self.pending[owner] = False
            del self.order_owners[order_event.OrderId]

