class ParallelDailyStrategiesAlgorithm(QCAlgorithm):
    MOVING_AVERAGE_PERIOD = 20
    RSI_PERIOD = 14

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy_sma = SimpleMovingAverage(self.MOVING_AVERAGE_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.WILDERS
        )

        self.spy_close_history = RollingWindow[float](2)
        self.spy_sma_history = RollingWindow[float](2)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0
        self.strategy_a_order_pending = False
        self.strategy_b_order_pending = False
        self.order_owners = {}

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        # Market-state quantities continue to advance for every ticker whose bar
        # is present, even on a day on which trading rules must be skipped.
        spy_bar = bars.get("SPY")
        if spy_bar is not None:
            self.spy_sma.update(spy_bar.end_time, spy_bar.close)
            self.spy_close_history.add(float(spy_bar.close))
            if self.spy_sma.is_ready:
                self.spy_sma_history.add(float(self.spy_sma.current.value))

        aapl_bar = bars.get("AAPL")
        if aapl_bar is not None:
            close = float(aapl_bar.close)
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)
            if self.aapl_previous_close is not None:
                if close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = close

        if len(bars) != len(self.symbols):
            return

        # Sells are evaluated before buys. Each symbol is used by only its own
        # strategy, so its tracked shares are the strategy's private lot.
        self._evaluate_strategy_a_sell()
        self._evaluate_strategy_b_sell()
        self._evaluate_strategy_a_buy(spy_bar)
        self._evaluate_strategy_b_buy(aapl_bar)

    def _evaluate_strategy_a_sell(self):
        if (
            self.strategy_a_shares <= 0
            or self.strategy_a_order_pending
            or not self.spy_close_history.is_ready
            or not self.spy_sma_history.is_ready
        ):
            return

        crossed_below = (
            self.spy_close_history[1] >= self.spy_sma_history[1]
            and self.spy_close_history[0] < self.spy_sma_history[0]
        )
        if crossed_below:
            self._submit_order(
                "A", -self.strategy_a_shares, "Strategy A: close crossed below SMA"
            )

    def _evaluate_strategy_b_sell(self):
        if (
            self.strategy_b_shares <= 0
            or self.strategy_b_order_pending
            or not self.aapl_rsi.is_ready
        ):
            return

        if self.aapl_rsi.current.value > 60:
            self._submit_order(
                "B", -self.strategy_b_shares, "Strategy B: RSI closed above 60"
            )

    def _evaluate_strategy_a_buy(self, bar: TradeBar):
        if (
            self.strategy_a_shares != 0
            or self.strategy_a_order_pending
            or not self.spy_close_history.is_ready
            or not self.spy_sma_history.is_ready
        ):
            return

        crossed_above = (
            self.spy_close_history[1] <= self.spy_sma_history[1]
            and self.spy_close_history[0] > self.spy_sma_history[0]
        )
        if crossed_above:
            quantity = floor(
                0.40 * float(self.portfolio.total_portfolio_value) / float(bar.close)
            )
            if quantity > 0:
                self._submit_order(
                    "A", quantity, "Strategy A: close crossed above SMA"
                )

    def _evaluate_strategy_b_buy(self, bar: TradeBar):
        if self.strategy_b_shares != 0 or self.strategy_b_order_pending:
            return

        if self.aapl_red_streak >= 3 and float(self.portfolio.cash) >= 20_000:
            quantity = floor(20_000 / float(bar.close))
            if quantity > 0:
                self._submit_order("B", quantity, "Strategy B: three red days")

    def _submit_order(self, owner, quantity, tag):
        symbol = self.symbols["SPY"] if owner == "A" else self.symbols["AAPL"]
        ticket = self.market_order(symbol, quantity, tag=tag)
        self.order_owners[ticket.order_id] = owner
        if owner == "A":
            self.strategy_a_order_pending = True
        else:
            self.strategy_b_order_pending = True

    def on_order_event(self, order_event: OrderEvent):
        owner = self.order_owners.get(order_event.order_id)
        if owner is None:
            return

        if order_event.fill_quantity != 0:
            if owner == "A":
                self.strategy_a_shares += int(order_event.fill_quantity)
            else:
                self.strategy_b_shares += int(order_event.fill_quantity)

        if order_event.status in (OrderStatus.FILLED, OrderStatus.CANCELED, OrderStatus.INVALID):
            if owner == "A":
                self.strategy_a_order_pending = False
            else:
                self.strategy_b_order_pending = False
            del self.order_owners[order_event.order_id]

