class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_average = SimpleMovingAverage(20)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_average = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        # Reconcile filled quantities (including split adjustments) without
        # treating a queued daily market order as an empty lot.
        if self.spy_lot > 0 and not self.Transactions.GetOpenOrders(self.spy):
            self.spy_lot = int(self.Portfolio[self.spy].Quantity)
        if self.aapl_lot > 0 and not self.Transactions.GetOpenOrders(self.aapl):
            self.aapl_lot = int(self.Portfolio[self.aapl].Quantity)

        # Keep each market-state quantity current even when another ticker's bar
        # is absent. Trading decisions below still require a complete daily slice.
        if data.Bars.ContainsKey(self.spy):
            spy_close = data.Bars[self.spy].Close
            self.spy_average.Update(data.Time, spy_close)
        else:
            spy_close = None

        if data.Bars.ContainsKey(self.aapl):
            aapl_close = data.Bars[self.aapl].Close
            self.aapl_rsi.Update(data.Time, aapl_close)
            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
        else:
            aapl_close = None

        complete_slice = all(data.Bars.ContainsKey(symbol) for symbol in self.symbols)
        indicators_ready = self.spy_average.IsReady and self.aapl_rsi.IsReady

        if complete_slice and indicators_ready:
            spy_average = self.spy_average.Current.Value

            # All sells are evaluated before any buys.
            if self.spy_lot > 0 and self._spy_crossed_below(spy_close, spy_average):
                self.MarketOrder(self.spy, -self.spy_lot)
                self.spy_lot = 0

            if self.aapl_lot > 0 and self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.aapl_lot)
                self.aapl_lot = 0

            if self.spy_lot == 0 and self._spy_crossed_above(spy_close, spy_average):
                quantity = self.CalculateOrderQuantity(self.spy, 0.40)
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)
                    self.spy_lot = quantity

            if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
                allocation = 20_000
                if self.Portfolio.Cash >= allocation:
                    quantity = floor(allocation / aapl_close)
                    if quantity > 0:
                        self.MarketOrder(self.aapl, quantity)
                        self.aapl_lot = quantity

        if spy_close is not None and self.spy_average.IsReady:
            self.previous_spy_close = spy_close
            self.previous_spy_average = self.spy_average.Current.Value

        if aapl_close is not None:
            self.previous_aapl_close = aapl_close

    def _spy_crossed_above(self, close, average):
        return (
            self.previous_spy_close is not None
            and self.previous_spy_average is not None
            and self.previous_spy_close <= self.previous_spy_average
            and close > average
        )

    def _spy_crossed_below(self, close, average):
        return (
            self.previous_spy_close is not None
            and self.previous_spy_average is not None
            and self.previous_spy_close >= self.previous_spy_average
            and close < average
        )

