class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy_closes = deque(maxlen=20)
        self.previous_spy_close = None
        self.previous_spy_average = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.spy_lot = 0
        self.aapl_lot = 0

    def on_data(self, data):
        spy_bar = data.bars.get(self.symbols["SPY"])
        aapl_bar = data.bars.get(self.symbols["AAPL"])

        current_spy_average = None
        if spy_bar is not None:
            self.spy_closes.append(spy_bar.close)
            if len(self.spy_closes) == self.spy_closes.maxlen:
                current_spy_average = sum(self.spy_closes) / Decimal(len(self.spy_closes))

        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        complete_slice = all(data.bars.get(symbol) is not None for symbol in self.symbols.values())
        if complete_slice:
            self._run_spy_strategy(spy_bar.close, current_spy_average)
            self._run_aapl_strategy(aapl_bar.close)

        if spy_bar is not None:
            self.previous_spy_close = spy_bar.close
            self.previous_spy_average = current_spy_average
        if aapl_bar is not None:
            self.previous_aapl_close = aapl_bar.close

    def _run_spy_strategy(self, close, average):
        if average is None or self.previous_spy_average is None:
            return

        crossed_above = (
            self.previous_spy_close <= self.previous_spy_average
            and close > average
        )
        crossed_below = (
            self.previous_spy_close >= self.previous_spy_average
            and close < average
        )

        if self.spy_lot > 0:
            if crossed_below:
                self.market_order(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0
        elif crossed_above:
            quantity = self.calculate_order_quantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

    def _run_aapl_strategy(self, close):
        if not self.aapl_rsi.is_ready:
            return

        if self.aapl_lot > 0:
            if self.aapl_rsi.current.value > 60:
                self.market_order(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0
        elif self.aapl_red_streak >= 3 and self.portfolio.cash >= 20_000:
            quantity = int(Decimal(20_000) // close)
            if quantity > 0:
                self.market_order(self.symbols["AAPL"], quantity)
                self.aapl_lot = quantity

