class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        # A simple 20-trading-day average is used as Strategy A's moving average.
        self.spy_average = self.SMA(self.symbols["SPY"], 20, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.symbols["AAPL"], 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.previous_spy_close = None
        self.previous_spy_average = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        # This supplies the previous price and a fully formed 20-day average on
        # the first backtest bar without changing the requested backtest dates.
        self.SetWarmUp(21, Resolution.Daily)

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        # Market-state quantities continue to advance even on a date on which
        # another subscription has no bar.
        if data.Bars.ContainsKey(aapl):
            aapl_close = data.Bars[aapl].Close
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_close

        spy_crossed_above = False
        spy_crossed_below = False
        if data.Bars.ContainsKey(spy) and self.spy_average.IsReady:
            spy_close = data.Bars[spy].Close
            spy_average = self.spy_average.Current.Value
            if self.previous_spy_close is not None and self.previous_spy_average is not None:
                spy_crossed_above = (
                    self.previous_spy_close <= self.previous_spy_average
                    and spy_close > spy_average
                )
                spy_crossed_below = (
                    self.previous_spy_close >= self.previous_spy_average
                    and spy_close < spy_average
                )
            self.previous_spy_close = spy_close
            self.previous_spy_average = spy_average

        if self.IsWarmingUp:
            return

        # A missing daily bar for even one subscription suppresses every rule.
        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        # Sells are evaluated before buys.  Each strategy's share count is its
        # private lot; neither strategy can dispose of shares it did not buy.
        if self.strategy_a_shares > 0 and spy_crossed_below:
            self.MarketOrder(spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi.IsReady:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_crossed_above:
            close = data.Bars[spy].Close
            shares = floor(0.40 * self.Portfolio.TotalPortfolioValue / close)
            if shares > 0:
                self.MarketOrder(spy, shares)
                self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20_000:
                close = data.Bars[aapl].Close
                shares = floor(20_000 / close)
                if shares > 0:
                    self.MarketOrder(aapl, shares)
                    self.strategy_b_shares = shares

