class IndependentSpyAndAaplStrategies(QCAlgorithm):
    """Two independent daily strategies with separately tracked share lots."""

    MOVING_AVERAGE_PERIOD = 20

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.close_windows = {
            symbol: deque(maxlen=self.MOVING_AVERAGE_PERIOD)
            for symbol in self.symbols.values()
        }
        self.previous_closes = {symbol: None for symbol in self.symbols.values()}
        self.red_streaks = {symbol: 0 for symbol in self.symbols.values()}

        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.WILDERS
        )

        # Each number is the size of the private lot belonging to its strategy.
        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if symbol in data.bars:
                bars[ticker] = data.bars[symbol]

        # Market-state quantities continue to consume every available bar even
        # when a missing subscription forces all trading rules to be skipped.
        spy_cross_above = False
        spy_cross_below = False
        spy = self.symbols["SPY"]
        if "SPY" in bars:
            spy_bar = bars["SPY"]
            spy_window = self.close_windows[spy]
            if len(spy_window) == self.MOVING_AVERAGE_PERIOD:
                yesterday_close = spy_window[-1]
                yesterday_average = sum(spy_window) / len(spy_window)
                today_average = (
                    sum(list(spy_window)[1:]) + float(spy_bar.close)
                ) / self.MOVING_AVERAGE_PERIOD
                spy_cross_above = (
                    yesterday_close <= yesterday_average
                    and float(spy_bar.close) > today_average
                )
                spy_cross_below = (
                    yesterday_close >= yesterday_average
                    and float(spy_bar.close) < today_average
                )

        for ticker, bar in bars.items():
            symbol = self.symbols[ticker]
            close = float(bar.close)
            previous_close = self.previous_closes[symbol]
            if previous_close is not None and close < previous_close:
                self.red_streaks[symbol] += 1
            else:
                self.red_streaks[symbol] = 0
            self.previous_closes[symbol] = close
            self.close_windows[symbol].append(close)

        if "AAPL" in bars:
            aapl_bar = bars["AAPL"]
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        if len(bars) != len(self.symbols):
            return

        # Evaluate every sell before evaluating either strategy's buy.
        if self.strategy_a_shares > 0 and spy_cross_below:
            self.market_order(spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        aapl = self.symbols["AAPL"]
        if (
            self.strategy_b_shares > 0
            and self.aapl_rsi.is_ready
            and self.aapl_rsi.current.value > 60
        ):
            self.market_order(aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_cross_above:
            shares = floor(
                0.40 * float(self.portfolio.total_portfolio_value)
                / float(bars["SPY"].close)
            )
            if shares > 0:
                self.market_order(spy, shares)
                self.strategy_a_shares = shares

        if (
            self.strategy_b_shares == 0
            and self.red_streaks[aapl] >= 3
            and float(self.portfolio.cash) >= 20_000
        ):
            shares = floor(20_000 / float(bars["AAPL"].close))
            if shares > 0:
                self.market_order(aapl, shares)
                self.strategy_b_shares = shares

