    """Two independent, close-driven strategy lots."""

    MOVING_AVERAGE_PERIOD = 20

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy_closes = deque(maxlen=self.MOVING_AVERAGE_PERIOD + 1)
        self.aapl_closes = deque(maxlen=15)
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        # Each strategy owns only the shares recorded in its private lot.
        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        spy_bar = data.bars.get(self.symbols["SPY"])
        aapl_bar = data.bars.get(self.symbols["AAPL"])

        # Market-state quantities continue to consume every available ticker bar.
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.close))

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.close)
            if self.aapl_closes:
                if aapl_close < self.aapl_closes[-1]:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_closes.append(aapl_close)
            self.aapl_rsi.update(aapl_bar.end_time, aapl_close)

        # A single absent subscription suppresses every rule for the day.
        if any(data.bars.get(symbol) is None for symbol in self.symbols.values()):
            return

        # Strategy A: sell before buy.
        if len(self.spy_closes) == self.spy_closes.maxlen:
            closes = list(self.spy_closes)
            previous_close = closes[-2]
            current_close = closes[-1]
            previous_average = sum(closes[:-1]) / self.MOVING_AVERAGE_PERIOD
            current_average = sum(closes[1:]) / self.MOVING_AVERAGE_PERIOD

            crosses_below = (
                previous_close >= previous_average
                and current_close < current_average
            )
            crosses_above = (
                previous_close <= previous_average
                and current_close > current_average
            )

            if self.strategy_a_shares > 0 and crosses_below:
                self.market_order(self.symbols["SPY"], -self.strategy_a_shares)
                self.strategy_a_shares = 0
            elif self.strategy_a_shares == 0 and crosses_above:
                quantity = floor(
                    0.40 * float(self.portfolio.total_portfolio_value) / current_close
                )
                if quantity > 0:
                    self.market_order(self.symbols["SPY"], quantity)
                    self.strategy_a_shares = quantity

        # Strategy B: sell before buy. RSI readiness also ensures its full history.
        if self.aapl_rsi.is_ready:
            if (
                self.strategy_b_shares > 0
                and float(self.aapl_rsi.current.value) > 60.0
            ):
                self.market_order(self.symbols["AAPL"], -self.strategy_b_shares)
                self.strategy_b_shares = 0
            elif self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
                cash_to_invest = 20_000.0
                if float(self.portfolio.cash) >= cash_to_invest:
                    quantity = floor(cash_to_invest / float(aapl_bar.close))
                    if quantity > 0:
                        self.market_order(self.symbols["AAPL"], quantity)
                        self.strategy_b_shares = quantity

