class IndependentSpyAaplStrategies(QCAlgorithm):
    """Two independent, close-of-day equity strategies with private lots."""

    MOVING_AVERAGE_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG")
        }

        self.spy_sma = self.SMA(
            self.symbols["SPY"], self.MOVING_AVERAGE_PERIOD, Resolution.Daily
        )
        self.aapl_rsi = self.RSI(
            self.symbols["AAPL"], 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.previous_closes = {}
        self.previous_spy_sma = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

        self.SetWarmUp(self.MOVING_AVERAGE_PERIOD + 1, Resolution.Daily)

    def OnData(self, data: Slice):
        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        closes = {
            ticker: data.Bars[symbol].Close
            for ticker, symbol in self.symbols.items()
        }

        previous_aapl_close = self.previous_closes.get("AAPL")
        if previous_aapl_close is not None:
            if closes["AAPL"] < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        indicators_ready = self.spy_sma.IsReady and self.aapl_rsi.IsReady
        history_ready = (
            "SPY" in self.previous_closes
            and previous_aapl_close is not None
            and self.previous_spy_sma is not None
        )

        if not self.IsWarmingUp and indicators_ready and history_ready:
            self._run_spy_strategy(closes["SPY"])
            self._run_aapl_strategy(closes["AAPL"])

        self.previous_closes = closes
        if self.spy_sma.IsReady:
            self.previous_spy_sma = self.spy_sma.Current.Value

    def _run_spy_strategy(self, close):
        symbol = self.symbols["SPY"]
        moving_average = self.spy_sma.Current.Value

        if self.spy_lot > 0:
            crossed_below = (
                self.previous_closes["SPY"] >= self.previous_spy_sma
                and close < moving_average
            )
            if crossed_below:
                self.MarketOrder(symbol, -int(self.Portfolio[symbol].Quantity))
                self.spy_lot = 0
            return

        crossed_above = (
            self.previous_closes["SPY"] <= self.previous_spy_sma
            and close > moving_average
        )
        if crossed_above:
            target_value = self.Portfolio.TotalPortfolioValue * 0.40
            quantity = int(target_value / close)
            if quantity > 0:
                self.MarketOrder(symbol, quantity)
                self.spy_lot = quantity

    def _run_aapl_strategy(self, close):
        symbol = self.symbols["AAPL"]

        if self.aapl_lot > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(symbol, -int(self.Portfolio[symbol].Quantity))
                self.aapl_lot = 0
            return

        if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
            quantity = int(20_000 / close)
            if quantity > 0:
                self.MarketOrder(symbol, quantity)
                self.aapl_lot = quantity

