class IndependentSpyAaplStrategies(QCAlgorithm):
    """Two independent daily strategies with separately tracked lots."""

    MOVING_AVERAGE_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=self.MOVING_AVERAGE_PERIOD)
        self.previous_spy_close = None
        self.previous_spy_average = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.Wilders
        )

        # These quantities belong exclusively to their respective strategies.
        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        bars = data.Bars

        # Market-state quantities are updated whenever their own ticker has data,
        # even when a different missing ticker makes this an evaluation-free bar.
        spy_bar = bars[self.symbols["SPY"]] if bars.ContainsKey(self.symbols["SPY"]) else None
        aapl_bar = bars[self.symbols["AAPL"]] if bars.ContainsKey(self.symbols["AAPL"]) else None

        spy_close = None
        spy_average = None
        if spy_bar is not None:
            spy_close = float(spy_bar.Close)
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == self.MOVING_AVERAGE_PERIOD:
                spy_average = sum(self.spy_closes) / self.MOVING_AVERAGE_PERIOD

        aapl_close = None
        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        complete_bar = all(bars.ContainsKey(symbol) for symbol in self.symbols.values())
        if complete_bar:
            self._evaluate_spy(spy_close, spy_average)
            self._evaluate_aapl(aapl_close)

        if spy_bar is not None:
            self.previous_spy_close = spy_close
            self.previous_spy_average = spy_average
        if aapl_bar is not None:
            self.previous_aapl_close = aapl_close

    def _evaluate_spy(self, close, average):
        ready = average is not None and self.previous_spy_average is not None
        if not ready or self.previous_spy_close is None:
            return

        crossed_below = (
            self.previous_spy_close >= self.previous_spy_average
            and close < average
        )
        crossed_above = (
            self.previous_spy_close <= self.previous_spy_average
            and close > average
        )

        # Sells are evaluated before buys, and only the applicable side is tested.
        if self.spy_lot > 0:
            if crossed_below:
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0
            return

        if crossed_above:
            quantity = int(self.CalculateOrderQuantity(self.symbols["SPY"], 0.40))
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

    def _evaluate_aapl(self, close):
        if self.aapl_lot > 0:
            if self.aapl_rsi.IsReady and float(self.aapl_rsi.Current.Value) > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0
            return

        if not self.aapl_rsi.IsReady or self.aapl_red_streak < 3:
            return

        cash_required = 20_000
        available_cash = float(self.Portfolio.CashBook["USD"].Amount)
        if available_cash >= cash_required:
            quantity = int(cash_required // close)
            if quantity > 0:
                self.MarketOrder(self.symbols["AAPL"], quantity)
                self.aapl_lot = quantity

