class IndependentSpyAaplStrategies(QCAlgorithm):
    """Two independent, close-of-day strategies with separately tracked lots."""

    SPY_MOVING_AVERAGE_PERIOD = 50

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=self.SPY_MOVING_AVERAGE_PERIOD)
        self.spy_previous_close = None
        self.spy_previous_average = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        # Market-state quantities continue to advance whenever their data exists,
        # even on a day on which trading rules must be skipped.
        spy_today_average = None
        if "SPY" in bars:
            spy_close = float(bars["SPY"].Close)
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == self.SPY_MOVING_AVERAGE_PERIOD:
                spy_today_average = sum(self.spy_closes) / len(self.spy_closes)

        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].Close)
            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi.Update(data.Time, aapl_close)

        all_bars_present = len(bars) == len(self.symbols)
        if all_bars_present:
            self._synchronize_filled_lots()

            # Sells are evaluated before either independent slot's buy.
            spy_crossed_below = (
                self.spy_lot > 0
                and self.spy_previous_close is not None
                and self.spy_previous_average is not None
                and spy_today_average is not None
                and self.spy_previous_close >= self.spy_previous_average
                and spy_close < spy_today_average
            )
            if spy_crossed_below:
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot, tag="Strategy A sell")
                self.spy_lot = 0

            if (
                self.aapl_lot > 0
                and self.aapl_rsi.IsReady
                and float(self.aapl_rsi.Current.Value) > 60
            ):
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot, tag="Strategy B sell")
                self.aapl_lot = 0

            spy_crossed_above = (
                self.spy_lot == 0
                and self.spy_previous_close is not None
                and self.spy_previous_average is not None
                and spy_today_average is not None
                and self.spy_previous_close <= self.spy_previous_average
                and spy_close > spy_today_average
            )
            if spy_crossed_above:
                allocation = 0.40 * float(self.Portfolio.TotalPortfolioValue)
                quantity = int(allocation / spy_close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["SPY"], quantity, tag="Strategy A buy")
                    self.spy_lot = quantity

            if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
                purchase_value = 20_000
                if float(self.Portfolio.Cash) >= purchase_value:
                    quantity = int(purchase_value / aapl_close)
                    if quantity > 0:
                        self.MarketOrder(self.symbols["AAPL"], quantity, tag="Strategy B buy")
                        self.aapl_lot = quantity

        if "SPY" in bars:
            self.spy_previous_close = spy_close
            self.spy_previous_average = spy_today_average
        if "AAPL" in bars:
            self.aapl_previous_close = aapl_close

    def _synchronize_filled_lots(self):
        """Keep private lots aligned with fills and split-adjusted holdings."""
        spy_holding = int(self.Portfolio[self.symbols["SPY"]].Quantity)
        if self.spy_lot > 0 and spy_holding > 0:
            self.spy_lot = spy_holding

        aapl_holding = int(self.Portfolio[self.symbols["AAPL"]].Quantity)
        if self.aapl_lot > 0 and aapl_holding > 0:
            self.aapl_lot = aapl_holding

