            aapl_close = bars[aapl].close
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.update(data.time, aapl_close)
        else:
            aapl_close = None

        all_bars_present = all(
            bars.contains_key(symbol) for symbol in self.symbols.values()
        )
        indicators_ready = self.spy_sma.is_ready and self.aapl_rsi.is_ready

        if all_bars_present and indicators_ready:
            self._evaluate_spy(spy, spy_close, spy_sma)
            self._evaluate_aapl(aapl, aapl_close)

        if spy_close is not None:
            self.spy_previous_close = spy_close
            self.spy_previous_sma = spy_sma
        if aapl_close is not None:
            self.aapl_previous_close = aapl_close

    def _evaluate_spy(self, symbol, close, moving_average):
        if self.spy_previous_sma is None:
            return

        crosses_below = (
            self.spy_previous_close >= self.spy_previous_sma
            and close < moving_average
        )
        crosses_above = (
            self.spy_previous_close <= self.spy_previous_sma
            and close > moving_average
        )

        if self.spy_lot > 0 and crosses_below:
            self.market_order(symbol, -self.spy_lot)
            self.spy_lot = 0

        if self.spy_lot == 0 and crosses_above:
            quantity = int(
                (self.portfolio.total_portfolio_value * 0.40) // close
            )
            if quantity > 0:
                self.market_order(symbol, quantity)
                self.spy_lot = quantity

    def _evaluate_aapl(self, symbol, close):
        if self.aapl_lot > 0 and self.aapl_rsi.current.value > 60:
            self.market_order(symbol, -self.aapl_lot)
            self.aapl_lot = 0

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            if self.portfolio.cash >= 20_000:
                quantity = int(20_000 // close)
                if quantity > 0:
                    self.market_order(symbol, quantity)
                    self.aapl_lot = quantity

