        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

    def on_data(self, data: Slice):
        bars = data.bars

        spy_bar = bars.get(self.symbols["SPY"])
        aapl_bar = bars.get(self.symbols["AAPL"])

        if spy_bar is not None:
            self.spy_sma.update(spy_bar.end_time, spy_bar.close)

        if aapl_bar is not None:
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)
            if self.previous_aapl_close is not None:
                if aapl_bar.close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

        all_bars_present = all(
            bars.get(symbol) is not None for symbol in self.symbols.values()
        )

        if all_bars_present:
            self._run_spy_strategy(spy_bar)
            self._run_aapl_strategy(aapl_bar)

        if spy_bar is not None:
            self.previous_spy_close = spy_bar.close
            self.previous_spy_sma = (
                self.spy_sma.current.value if self.spy_sma.is_ready else None
            )

        if aapl_bar is not None:
            self.previous_aapl_close = aapl_bar.close

    def _run_spy_strategy(self, bar: TradeBar):
        if not self.spy_sma.is_ready or self.previous_spy_sma is None:
            return

        close = bar.close
        average = self.spy_sma.current.value

        crossed_below = (
            self.previous_spy_close >= self.previous_spy_sma
            and close < average
        )
        if self.spy_lot > 0 and crossed_below:
            self.market_order(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0
            return

        crossed_above = (
            self.previous_spy_close <= self.previous_spy_sma
            and close > average
        )
        if self.spy_lot == 0 and crossed_above:
            quantity = int((self.portfolio.total_portfolio_value * 0.40) / close)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

    def _run_aapl_strategy(self, bar: TradeBar):
        if not self.aapl_rsi.is_ready:
            return

        if self.aapl_lot > 0 and self.aapl_rsi.current.value > 60:
            self.market_order(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0
            return

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            allocation = 20_000
            if self.portfolio.cash >= allocation:
                quantity = int(allocation / bar.close)
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

