class IndependentDailyStrategiesAlgorithm(QCAlgorithm):
    MOVING_AVERAGE_PERIOD = 20
    RSI_PERIOD = 14

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            security = self.add_equity(ticker, Resolution.DAILY)
            security.set_data_normalization_mode(DataNormalizationMode.ADJUSTED)
            self.symbols[ticker] = security.symbol

        self.spy_closes = deque(maxlen=self.MOVING_AVERAGE_PERIOD)
        self.spy_previous_close = None
        self.spy_previous_average = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.WILDERS
        )

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if symbol in data.bars:
                bars[ticker] = data.bars[symbol]

        spy_bar = bars.get("SPY")
        spy_close = None
        spy_average = None
        spy_ready = False
        if spy_bar is not None:
            spy_close = float(spy_bar.close)
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == self.MOVING_AVERAGE_PERIOD:
                spy_average = sum(self.spy_closes) / self.MOVING_AVERAGE_PERIOD
                spy_ready = (
                    self.spy_previous_close is not None
                    and self.spy_previous_average is not None
                )

        aapl_bar = bars.get("AAPL")
        aapl_close = None
        if aapl_bar is not None:
            aapl_close = float(aapl_bar.close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        complete_day = len(bars) == len(self.symbols)
        if complete_day:
            self._evaluate_strategy_a(spy_close, spy_average, spy_ready)
            self._evaluate_strategy_b(aapl_close)

        if spy_bar is not None:
            self.spy_previous_close = spy_close
            if spy_average is not None:
                self.spy_previous_average = spy_average
        if aapl_bar is not None:
            self.aapl_previous_close = aapl_close

    def _evaluate_strategy_a(self, close, average, ready):
        if not ready:
            return

        crossed_below = (
            self.spy_previous_close >= self.spy_previous_average
            and close < average
        )
        crossed_above = (
            self.spy_previous_close <= self.spy_previous_average
            and close > average
        )

        symbol = self.symbols["SPY"]
        if self.strategy_a_shares > 0:
            if crossed_below:
                self.market_order(symbol, -self.strategy_a_shares)
                self.strategy_a_shares = 0
        elif crossed_above:
            shares = floor(0.40 * float(self.portfolio.total_portfolio_value) / close)
            if shares > 0:
                self.market_order(symbol, shares)
                self.strategy_a_shares = shares

    def _evaluate_strategy_b(self, close):
        if not self.aapl_rsi.is_ready:
            return

        symbol = self.symbols["AAPL"]
        if self.strategy_b_shares > 0:
            if float(self.aapl_rsi.current.value) > 60:
                self.market_order(symbol, -self.strategy_b_shares)
                self.strategy_b_shares = 0
        elif self.aapl_red_streak >= 3 and float(self.portfolio.cash) >= 20_000:
            shares = floor(20_000 / close)
            if shares > 0:
                self.market_order(symbol, shares)
                self.strategy_b_shares = shares

