class IndependentSpyAaplStrategies(QCAlgorithm):
    """Two independent, privately accounted daily equity strategies."""

    SMA_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=self.SMA_PERIOD)
        self.spy_previous_relation = None
        self.spy_crossed_above = False
        self.spy_crossed_below = False

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        # These quantities account for each strategy's private lot.
        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        # Market-state quantities continue to update whenever their ticker has a bar.
        if "SPY" in bars:
            self._update_spy_state(float(bars["SPY"].Close))
        if "AAPL" in bars:
            self._update_aapl_state(bars["AAPL"])

        # A missing bar in any subscription suppresses every rule for the day.
        if len(bars) != len(self.symbols):
            return

        if not self._all_indicators_ready():
            return

        spy_close = float(bars["SPY"].Close)
        aapl_close = float(bars["AAPL"].Close)

        # All exits are evaluated before any entries.
        if self.strategy_a_shares > 0 and self.spy_crossed_below:
            self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and self.spy_crossed_above:
            quantity = math.floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / spy_close)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            cash = float(self.Portfolio.CashBook["USD"].Amount)
            if cash >= 20_000:
                quantity = math.floor(20_000 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.strategy_b_shares = quantity

    def _update_spy_state(self, close):
        self.spy_crossed_above = False
        self.spy_crossed_below = False
        self.spy_closes.append(close)

        if len(self.spy_closes) < self.SMA_PERIOD:
            return

        moving_average = sum(self.spy_closes) / self.SMA_PERIOD
        relation = close - moving_average
        if self.spy_previous_relation is not None:
            self.spy_crossed_above = self.spy_previous_relation <= 0 and relation > 0
            self.spy_crossed_below = self.spy_previous_relation >= 0 and relation < 0
        self.spy_previous_relation = relation

    def _update_aapl_state(self, bar):
        close = float(bar.Close)
        if self.aapl_previous_close is not None and close < self.aapl_previous_close:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0
        self.aapl_previous_close = close
        self.aapl_rsi.Update(IndicatorDataPoint(bar.EndTime, close))

    def _all_indicators_ready(self):
