class StrategySystemAlgorithm(QCAlgorithm):
    MOVING_AVERAGE_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy_sma = SimpleMovingAverage(self.MOVING_AVERAGE_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.Wilders
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_order_pending = False
        self.strategy_b_order_pending = False
        self.order_strategy = {}

    def OnData(self, data):
        bars = data.Bars
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        spy_crosses_above = False
        spy_crosses_below = False

        if bars.ContainsKey(spy):
            spy_close = bars[spy].Close
            self.spy_sma.Update(data.Time, spy_close)
            if self.spy_sma.IsReady:
                spy_sma = self.spy_sma.Current.Value
                if self.previous_spy_sma is not None:
                    spy_crosses_above = (
                        self.previous_spy_close <= self.previous_spy_sma
                        and spy_close > spy_sma
                    )
                    spy_crosses_below = (
                        self.previous_spy_close >= self.previous_spy_sma
                        and spy_close < spy_sma
                    )
                self.previous_spy_close = spy_close
                self.previous_spy_sma = spy_sma

        if bars.ContainsKey(aapl):
            aapl_close = bars[aapl].Close
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_close
            self.aapl_rsi.Update(data.Time, aapl_close)

        # Quantities above are maintained from every available bar, but no rule is
        # evaluated unless all five subscribed securities supplied today's bar.
        if any(not bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if not (self.spy_sma.IsReady and self.aapl_rsi.IsReady):
            return

        # Evaluate every sell before evaluating either buy.
        if (
            self.Portfolio[spy].Quantity > 0
            and not self.strategy_a_order_pending
            and spy_crosses_below
        ):
            self._submit_order(
                spy,
                -int(self.Portfolio[spy].Quantity),
                "A",
                "Strategy A sell",
            )

        if (
            self.Portfolio[aapl].Quantity > 0
            and not self.strategy_b_order_pending
            and self.aapl_rsi.Current.Value > 60
        ):
            self._submit_order(
                aapl,
                -int(self.Portfolio[aapl].Quantity),
                "B",
                "Strategy B sell",
            )

        if (
            self.Portfolio[spy].Quantity == 0
            and not self.strategy_a_order_pending
            and spy_crosses_above
        ):
            shares = int(
                (self.Portfolio.TotalPortfolioValue * 0.40)
                // bars[spy].Close
            )
            if shares > 0:
                self._submit_order(spy, shares, "A", "Strategy A buy")

        if (
            self.Portfolio[aapl].Quantity == 0
            and not self.strategy_b_order_pending
            and self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= 20_000
        ):
            shares = int(20_000 // bars[aapl].Close)
            if shares > 0:
                self._submit_order(aapl, shares, "B", "Strategy B buy")

    def _submit_order(self, symbol, quantity, strategy, tag):
        ticket = self.MarketOrder(symbol, quantity, False, tag)
        self.order_strategy[ticket.OrderId] = strategy
        if strategy == "A":
            self.strategy_a_order_pending = True
        else:
            self.strategy_b_order_pending = True

    def OnOrderEvent(self, order_event):
        if order_event.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            return

        strategy = self.order_strategy.pop(order_event.OrderId, None)
        if strategy == "A":
            self.strategy_a_order_pending = False
        elif strategy == "B":
            self.strategy_b_order_pending = False

