        self.spy_closes = deque(maxlen=20)
        self.previous_spy_close = None
        self.previous_spy_average = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.spy_lot = 0
        self.aapl_lot = 0

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        spy_average = None
        if "SPY" in bars:
            spy_close = float(bars["SPY"].close)
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == self.spy_closes.maxlen:
                spy_average = sum(self.spy_closes) / len(self.spy_closes)

        if "AAPL" in bars:
            aapl_bar = bars["AAPL"]
            aapl_close = float(aapl_bar.close)
            if self.previous_aapl_close is None or aapl_close >= self.previous_aapl_close:
                self.aapl_red_streak = 0
            else:
                self.aapl_red_streak += 1
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        complete_day = len(bars) == len(self.symbols)
        all_rules_ready = (
            spy_average is not None
            and self.previous_spy_average is not None
            and self.aapl_rsi.is_ready
        )
        if complete_day and all_rules_ready:
            self._evaluate_spy(spy_average, float(bars["SPY"].close))
            self._evaluate_aapl(float(bars["AAPL"].close))

        if "SPY" in bars:
            if spy_average is not None:
                self.previous_spy_close = float(bars["SPY"].close)
                self.previous_spy_average = spy_average
            else:
                self.previous_spy_close = None
                self.previous_spy_average = None

        if "AAPL" in bars:
            self.previous_aapl_close = float(bars["AAPL"].close)

    def _evaluate_spy(self, average, close):
        if average is None or self.previous_spy_average is None:
            return

        crossed_below = (
            self.previous_spy_close >= self.previous_spy_average
            and close < average
        )
        crossed_above = (
            self.previous_spy_close <= self.previous_spy_average
            and close > average
        )

        if self.spy_lot > 0:
            if crossed_below:
                self.market_order(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0
        elif crossed_above:
            quantity = floor(0.40 * float(self.portfolio.total_portfolio_value) / close)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

    def _evaluate_aapl(self, close):
        if not self.aapl_rsi.is_ready:
            return

        if self.aapl_lot > 0:
            if float(self.aapl_rsi.current.value) > 60:
                self.market_order(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0
        elif self.aapl_red_streak >= 3 and float(self.portfolio.cash) >= 20_000:
            quantity = floor(20_000 / close)
            if quantity > 0:
                self.market_order(self.symbols["AAPL"], quantity)
                self.aapl_lot = quantity

