class ParallelSpyAaplStrategies(QCAlgorithm):
    """Two independent daily strategies with separately accounted share lots."""

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG")
        }

        # A 20-bar simple moving average is used for Strategy A.
        self.spy_closes = deque(maxlen=21)
        self.previous_spy_close = None
        self.previous_spy_average = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi_change_count = 0
        self.aapl_average_gain = None
        self.aapl_average_loss = None
        self.aapl_seed_gain = 0.0
        self.aapl_seed_loss = 0.0
        self.aapl_rsi = None

        # Each entry is the number of shares owned by that strategy alone.
        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        # Market-state quantities consume every available bar, even on a date
        # on which a missing subscription prevents rules from being evaluated.
        spy_close = None
        spy_average = None
        if "SPY" in bars:
            spy_close = float(bars["SPY"].close)
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) >= 20:
                spy_average = sum(list(self.spy_closes)[-20:]) / 20.0

        aapl_close = None
        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].close)
            if self.previous_aapl_close is not None:
                change = aapl_close - self.previous_aapl_close
                self.aapl_red_streak = self.aapl_red_streak + 1 if change < 0 else 0
                gain = max(change, 0.0)
                loss = max(-change, 0.0)
                self.aapl_rsi_change_count += 1
                if self.aapl_rsi_change_count <= 14:
                    self.aapl_seed_gain += gain
                    self.aapl_seed_loss += loss
                    if self.aapl_rsi_change_count == 14:
                        self.aapl_average_gain = self.aapl_seed_gain / 14.0
                        self.aapl_average_loss = self.aapl_seed_loss / 14.0
                else:
                    self.aapl_average_gain = (13.0 * self.aapl_average_gain + gain) / 14.0
                    self.aapl_average_loss = (13.0 * self.aapl_average_loss + loss) / 14.0

                if self.aapl_average_gain is not None:
                    if self.aapl_average_loss == 0:
                        self.aapl_rsi = 100.0 if self.aapl_average_gain > 0 else 50.0
                    else:
                        relative_strength = self.aapl_average_gain / self.aapl_average_loss
                        self.aapl_rsi = 100.0 - 100.0 / (1.0 + relative_strength)

        all_bars_present = len(bars) == len(self.symbols)
        indicators_ready = (
            spy_average is not None
            and self.previous_spy_average is not None
            and self.previous_spy_close is not None
            and self.aapl_rsi is not None
            and self.previous_aapl_close is not None
        )

        if all_bars_present and indicators_ready:
            spy_crossed_below = (
                self.previous_spy_close >= self.previous_spy_average
                and spy_close < spy_average
            )

            # Sells for every independent strategy are evaluated before buys.
            if self.strategy_a_lot > 0 and spy_crossed_below:
                self.market_order(self.symbols["SPY"], -self.strategy_a_lot)
                self.strategy_a_lot = 0

            if self.strategy_b_lot > 0 and self.aapl_rsi > 60.0:
                self.market_order(self.symbols["AAPL"], -self.strategy_b_lot)
                self.strategy_b_lot = 0

            spy_crossed_above = (
                self.previous_spy_close <= self.previous_spy_average
                and spy_close > spy_average
            )
            if self.strategy_a_lot == 0 and spy_crossed_above:
                quantity = floor(0.40 * float(self.portfolio.total_portfolio_value) / spy_close)
                if quantity > 0:
                    self.market_order(self.symbols["SPY"], quantity)
                    self.strategy_a_lot = quantity

            if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
                if float(self.portfolio.cash) >= 20_000.0:
                    quantity = floor(20_000.0 / aapl_close)
                    if quantity > 0:
                        self.market_order(self.symbols["AAPL"], quantity)
                        self.strategy_b_lot = quantity

        if "SPY" in bars:
            self.previous_spy_close = spy_close
            self.previous_spy_average = spy_average
        if "AAPL" in bars:
            self.previous_aapl_close = aapl_close

