class IndependentStrategiesAlgorithm(QCAlgorithm):
    SPY_MOVING_AVERAGE_PERIOD = 20
    AAPL_RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            security = self.AddEquity(ticker, Resolution.Daily)
            security.SetDataNormalizationMode(DataNormalizationMode.Raw)
            self.symbols[ticker] = security.Symbol

        self.spy_closes = deque(maxlen=self.SPY_MOVING_AVERAGE_PERIOD)
        self.previous_spy_close = None
        self.previous_spy_average = None
        self.previous_spy_average_ready = False

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(
            self.AAPL_RSI_PERIOD, MovingAverageType.Wilders
        )

        self.spy_lot = 0
        self.aapl_lot = 0
        self.pending_orders = {}
        self.spy_order_pending = False
        self.aapl_order_pending = False

    def OnData(self, data: Slice):
        bars = data.Bars

        spy_bar = bars[self.symbols["SPY"]] if self.symbols["SPY"] in bars else None
        aapl_bar = bars[self.symbols["AAPL"]] if self.symbols["AAPL"] in bars else None

        current_spy_average = None
        current_spy_average_ready = False
        if spy_bar is not None:
            spy_close = Decimal(spy_bar.Close)
            self.spy_closes.append(spy_close)
            current_spy_average_ready = (
                len(self.spy_closes) == self.SPY_MOVING_AVERAGE_PERIOD
            )
            if current_spy_average_ready:
                current_spy_average = sum(self.spy_closes) / Decimal(
                    self.SPY_MOVING_AVERAGE_PERIOD
                )

        if aapl_bar is not None:
            aapl_close = Decimal(aapl_bar.Close)
            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        all_bars_present = all(
            symbol in bars for symbol in self.symbols.values()
        )

        if all_bars_present:
            all_indicators_ready = (
                current_spy_average_ready and self.aapl_rsi.IsReady
            )
            if all_indicators_ready:
                self._evaluate_spy(spy_bar.Close, current_spy_average)
                self._evaluate_aapl(aapl_bar.Close)

        if spy_bar is not None:
            self.previous_spy_close = Decimal(spy_bar.Close)
            self.previous_spy_average = current_spy_average
            self.previous_spy_average_ready = current_spy_average_ready
        if aapl_bar is not None:
            self.previous_aapl_close = Decimal(aapl_bar.Close)

    def _evaluate_spy(self, close, moving_average):
        close = Decimal(close)
        can_test_cross = (
            self.previous_spy_close is not None
            and self.previous_spy_average_ready
            and self.previous_spy_average is not None
        )
        if not can_test_cross or self.spy_order_pending:
            return

        crosses_below = (
            self.previous_spy_close >= self.previous_spy_average
            and close < moving_average
        )
        crosses_above = (
            self.previous_spy_close <= self.previous_spy_average
            and close > moving_average
        )

        if self.spy_lot > 0:
            if crosses_below:
                self._place_lot_order("SPY", -self.spy_lot)
        elif crosses_above:
            quantity = int(
                (Decimal("0.40") * Decimal(self.Portfolio.TotalPortfolioValue))
                // close
            )
            if quantity > 0:
                self._place_lot_order("SPY", quantity)

    def _evaluate_aapl(self, close):
        if self.aapl_order_pending:
            return

        if self.aapl_lot > 0:
            if Decimal(self.aapl_rsi.Current.Value) > Decimal("60"):
                self._place_lot_order("AAPL", -self.aapl_lot)
        elif self.aapl_red_streak >= 3:
            cash_to_invest = Decimal("20000")
            if Decimal(self.Portfolio.Cash) >= cash_to_invest:
                quantity = int(cash_to_invest // Decimal(close))
                if quantity > 0:
                    self._place_lot_order("AAPL", quantity)

    def _place_lot_order(self, ticker, quantity):
        ticket = self.MarketOrder(self.symbols[ticker], quantity)
        self.pending_orders[ticket.OrderId] = ticker
        if ticker == "SPY":
            self.spy_order_pending = True
        else:
            self.aapl_order_pending = True

    def OnOrderEvent(self, order_event: OrderEvent):
        order_id = order_event.OrderId
        if order_id not in self.pending_orders:
            return

        ticker = self.pending_orders[order_id]
        fill_quantity = int(order_event.FillQuantity)
        if ticker == "SPY":
            self.spy_lot = max(0, self.spy_lot + fill_quantity)
        else:
            self.aapl_lot = max(0, self.aapl_lot + fill_quantity)

        if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            del self.pending_orders[order_id]
            if ticker == "SPY":
                self.spy_order_pending = False
            else:
                self.aapl_order_pending = False

