class DailyParallelStrategiesAlgorithm(QCAlgorithm):
    MOVING_AVERAGE_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=self.MOVING_AVERAGE_PERIOD)
        self.spy_previous_close = None
        self.spy_previous_average = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.Wilders
        )

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        bars = data.Bars
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        # Market state is updated whenever that ticker has a bar, even on a day
        # when another subscription is missing and trading rules must be skipped.
        if spy in bars:
            spy_close = float(bars[spy].Close)
            spy_average = None
            if len(self.spy_closes) == self.MOVING_AVERAGE_PERIOD - 1:
                spy_average = (sum(self.spy_closes) + spy_close) / self.MOVING_AVERAGE_PERIOD
            elif len(self.spy_closes) == self.MOVING_AVERAGE_PERIOD:
                spy_average = (
                    sum(self.spy_closes) - self.spy_closes[0] + spy_close
                ) / self.MOVING_AVERAGE_PERIOD
            self.spy_closes.append(spy_close)
        else:
            spy_close = None
            spy_average = None

        if aapl in bars:
            aapl_bar = bars[aapl]
            aapl_close = float(aapl_bar.Close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)
        else:
            aapl_close = None

        have_every_bar = all(symbol in bars for symbol in self.symbols.values())
        if have_every_bar:
            self._evaluate_strategy_a(spy_close, spy_average)
            self._evaluate_strategy_b(aapl_close)

        if spy_close is not None:
            self.spy_previous_close = spy_close
            self.spy_previous_average = spy_average
        if aapl_close is not None:
            self.aapl_previous_close = aapl_close

    def _evaluate_strategy_a(self, close, average):
        if average is None or self.spy_previous_average is None:
            return

        crossed_below = (
            self.spy_previous_close >= self.spy_previous_average
            and close < average
        )
        crossed_above = (
            self.spy_previous_close <= self.spy_previous_average
            and close > average
        )

        # Sells are evaluated before buys, and each side is gated by this
        # strategy's private lot.
        if self.strategy_a_shares > 0:
            if crossed_below:
                self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
                self.strategy_a_shares = 0
            return

        if crossed_above:
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = floor(target_value / close)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.strategy_a_shares = quantity

    def _evaluate_strategy_b(self, close):
        if not self.aapl_rsi.IsReady:
            return

        if self.strategy_b_shares > 0:
            if float(self.aapl_rsi.Current.Value) > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
                self.strategy_b_shares = 0
            return

        cash_to_invest = 20_000
        if (
            self.aapl_red_streak >= 3
            and float(self.Portfolio.Cash) >= cash_to_invest
        ):
            quantity = floor(cash_to_invest / close)
            if quantity > 0:
                self.MarketOrder(self.symbols["AAPL"], quantity)
                self.strategy_b_shares = quantity

