        if "SPY" in bars:
            self.spy_closes.append(float(bars["SPY"].Close))

        if "AAPL" in bars:
            aapl_bar = bars["AAPL"]
            aapl_close = float(aapl_bar.Close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if len(bars) != len(self.tickers):
            self._remember_spy_cross_values(bars)
            return

        spy_close = float(bars["SPY"].Close)
        spy_average = self._spy_average()

        # All sell rules are evaluated before either strategy's buy rule.
        if self.spy_lot > 0 and self._spy_crosses_below(spy_close, spy_average):
            self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if (
            self.aapl_lot > 0
            and self.aapl_rsi.IsReady
            and float(self.aapl_rsi.Current.Value) > 60
        ):
            self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and self._spy_crosses_above(spy_close, spy_average):
            quantity = floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / spy_close)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if (
            self.aapl_lot == 0
            and self.aapl_rsi.IsReady
            and self.aapl_red_streak >= 3
            and float(self.Portfolio.Cash) >= 20_000
        ):
            quantity = floor(20_000 / float(bars["AAPL"].Close))
            if quantity > 0:
                self.MarketOrder(self.symbols["AAPL"], quantity)
                self.aapl_lot = quantity

        if spy_average is not None:
            self.previous_spy_close = spy_close
            self.previous_spy_average = spy_average

    def _spy_average(self):
        if len(self.spy_closes) < 20:
            return None
        closes = list(self.spy_closes)
        return sum(closes[-20:]) / 20.0

    def _remember_spy_cross_values(self, bars):
        if "SPY" not in bars:
            return
        spy_average = self._spy_average()
        if spy_average is not None:
            self.previous_spy_close = float(bars["SPY"].Close)
            self.previous_spy_average = spy_average

    def _spy_crosses_above(self, close, average):
        return (
            average is not None
            and self.previous_spy_close is not None
            and self.previous_spy_average is not None
            and self.previous_spy_close <= self.previous_spy_average
            and close > average
        )

    def _spy_crosses_below(self, close, average):
        return (
            average is not None
            and self.previous_spy_close is not None
            and self.previous_spy_average is not None
            and self.previous_spy_close >= self.previous_spy_average
            and close < average
        )

