            return

        if (len(self.spy_closes) < self.MOVING_AVERAGE_PERIOD + 1
                or self.aapl_rsi is None):
            return

        spy_close = float(data.Bars[spy].Close)
        previous_spy_close = self.spy_closes[-2]
        previous_sma = sum(list(self.spy_closes)[:-1]) / self.MOVING_AVERAGE_PERIOD
        current_sma = sum(list(self.spy_closes)[1:]) / self.MOVING_AVERAGE_PERIOD

        spy_crossed_below = (
            previous_spy_close >= previous_sma and spy_close < current_sma
        )
        spy_crossed_above = (
            previous_spy_close <= previous_sma and spy_close > current_sma
        )

        # Every strategy's sell is evaluated before any strategy's buy.
        if self.spy_lot > 0 and spy_crossed_below:
            self.MarketOrder(spy, -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi > 60:
            self.MarketOrder(aapl, -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_crossed_above:
            quantity = floor(0.40 * float(self.Portfolio.TotalPortfolioValue) /
                             spy_close)
            if quantity > 0:
                self.MarketOrder(spy, quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            cash_to_invest = 20_000
            if float(self.Portfolio.Cash) >= cash_to_invest:
                quantity = floor(cash_to_invest /
                                 float(data.Bars[aapl].Close))
                if quantity > 0:
                    self.MarketOrder(aapl, quantity)
                    self.aapl_lot = quantity

    def _update_aapl_state(self, close):
        if self.aapl_previous_close is not None:
            if close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        if self.rsi_previous_close is not None:
            change = close - self.rsi_previous_close
            gain = max(change, 0.0)
            loss = max(-change, 0.0)

            if self.rsi_change_count < 14:
                self.rsi_seed_gain += gain
                self.rsi_seed_loss += loss
                self.rsi_change_count += 1
                if self.rsi_change_count == 14:
                    self.rsi_average_gain = self.rsi_seed_gain / 14
                    self.rsi_average_loss = self.rsi_seed_loss / 14
            else:
                self.rsi_average_gain = (
                    self.rsi_average_gain * 13 + gain
                ) / 14
                self.rsi_average_loss = (
                    self.rsi_average_loss * 13 + loss
                ) / 14

            if self.rsi_average_gain is not None:
                if self.rsi_average_loss == 0:
                    self.aapl_rsi = 100.0
                else:
                    relative_strength = (
                        self.rsi_average_gain / self.rsi_average_loss
                    )
                    self.aapl_rsi = 100.0 - 100.0 / (1.0 + relative_strength)

        self.aapl_previous_close = close
        self.rsi_previous_close = close

