class ParallelSpyAaplStrategies(QCAlgorithm):
    MOVING_AVERAGE_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=self.MOVING_AVERAGE_PERIOD + 1)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0
        self.pending_orders = {}
        self.pending_strategy = {"spy": False, "aapl": False}

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(spy):
            self.spy_closes.append(float(data.Bars[spy].Close))

        if data.Bars.ContainsKey(aapl):
            bar = data.Bars[aapl]
            close = float(bar.Close)
            if self.aapl_previous_close is not None:
                if close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = close
            self.aapl_rsi.Update(bar.EndTime, bar.Close)

        # A day is actionable only when every subscription supplied its bar.
        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if (len(self.spy_closes) < self.MOVING_AVERAGE_PERIOD + 1
                or not self.aapl_rsi.IsReady):
            return

        spy_bar = data.Bars[spy]
        aapl_bar = data.Bars[aapl]

        previous_spy_close = self.spy_closes[-2]
        current_spy_close = self.spy_closes[-1]
        previous_spy_average = (
            sum(list(self.spy_closes)[:-1][-self.MOVING_AVERAGE_PERIOD:])
            / self.MOVING_AVERAGE_PERIOD
        )
        current_spy_average = (
            sum(list(self.spy_closes)[-self.MOVING_AVERAGE_PERIOD:])
            / self.MOVING_AVERAGE_PERIOD
        )

        # Sells are evaluated before buys for each independent strategy lot.
        if self.spy_lot > 0 and not self.pending_strategy["spy"]:
            if (previous_spy_close >= previous_spy_average
                    and current_spy_close < current_spy_average):
                self._submit("spy", spy, -self.spy_lot)
        elif self.spy_lot == 0 and not self.pending_strategy["spy"]:
            if (previous_spy_close <= previous_spy_average
                    and current_spy_close > current_spy_average):
                shares = floor(
                    0.40 * float(self.Portfolio.TotalPortfolioValue)
                    / float(spy_bar.Close)
                )
                if shares > 0:
                    self._submit("spy", spy, shares)

        if self.aapl_lot > 0 and not self.pending_strategy["aapl"]:
            if float(self.aapl_rsi.Current.Value) > 60:
                self._submit("aapl", aapl, -self.aapl_lot)
        elif self.aapl_lot == 0 and not self.pending_strategy["aapl"]:
            if self.aapl_red_streak >= 3 and float(self.Portfolio.Cash) >= 20_000:
                shares = floor(20_000 / float(aapl_bar.Close))
                if shares > 0:
                    self._submit("aapl", aapl, shares)

    def _submit(self, strategy, symbol, quantity):
        ticket = self.MarketOrder(symbol, quantity)
        self.pending_orders[ticket.OrderId] = strategy
        self.pending_strategy[strategy] = True

    def OnOrderEvent(self, order_event: OrderEvent):
        strategy = self.pending_orders.get(order_event.OrderId)
        if strategy is None:
            return

        if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            filled = int(order_event.FillQuantity)
            if strategy == "spy":
                self.spy_lot = max(0, self.spy_lot + filled)
            else:
                self.aapl_lot = max(0, self.aapl_lot + filled)

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            self.pending_strategy[strategy] = False
            del self.pending_orders[order_event.OrderId]

