class IndependentSpyAaplStrategies(QCAlgorithm):
    """Two independent, close-of-day strategy lots."""

    MOVING_AVERAGE_PERIOD = 20

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_closes = deque(maxlen=self.MOVING_AVERAGE_PERIOD)
        self.previous_spy_close = None
        self.previous_spy_average = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        # These quantities are private strategy lots, rather than aggregate
        # security holdings.  They are changed when an order is submitted so
        # a close-of-day signal cannot submit the same trade repeatedly.
        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        previous_spy_close, previous_spy_average = self._update_market_state(
            bars, self.time
        )

        # A partial subscribed universe invalidates every rule for this bar.
        if len(bars) != len(self.symbols):
            return

        if not self._all_state_is_ready():
            return

        spy = bars["SPY"]
        aapl = bars["AAPL"]
        spy_average = sum(self.spy_closes) / len(self.spy_closes)

        spy_crossed_below = (
            previous_spy_close is not None
            and previous_spy_average is not None
            and previous_spy_close >= previous_spy_average
            and spy.close < spy_average
        )
        spy_crossed_above = (
            previous_spy_close is not None
            and previous_spy_average is not None
            and previous_spy_close <= previous_spy_average
            and spy.close > spy_average
        )

        # All sells are evaluated before any buys.
        if self.strategy_a_shares > 0 and spy_crossed_below:
            self.market_order(self.symbols["SPY"], -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi.current.value > 60:
            self.market_order(self.symbols["AAPL"], -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_crossed_above:
            quantity = floor(0.40 * self.portfolio.total_portfolio_value / spy.close)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            cash_amount = 20_000
            if self.portfolio.cash >= cash_amount:
                quantity = floor(cash_amount / aapl.close)
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.strategy_b_shares = quantity

    def _update_market_state(self, bars, timestamp):
        previous_spy_close = self.previous_spy_close
        previous_spy_average = self.previous_spy_average
        spy = bars.get("SPY")
        if spy is not None:
            if len(self.spy_closes) == self.MOVING_AVERAGE_PERIOD:
                self.previous_spy_average = sum(self.spy_closes) / len(self.spy_closes)
            self.previous_spy_close = spy.close
            self.spy_closes.append(spy.close)

        aapl = bars.get("AAPL")
        if aapl is not None:
            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl.close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.previous_aapl_close = aapl.close
            self.aapl_rsi.update(timestamp, aapl.close)

        return previous_spy_close, previous_spy_average

    def _all_state_is_ready(self):
        return (
            len(self.spy_closes) == self.MOVING_AVERAGE_PERIOD
            and self.previous_spy_average is not None
            and self.previous_aapl_close is not None
            and self.aapl_rsi.is_ready
        )

