        self.spy_closes = deque(maxlen=self.SPY_MA_PERIOD)
        self.previous_spy_close = None
        self.previous_spy_average = None
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(
            self.AAPL_RSI_PERIOD, MovingAverageType.Wilders
        )

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data: Slice):
        bars = data.Bars

        # Market-state calculations continue for every ticker whose bar arrived.
        spy_bar = bars.get(self.symbols["SPY"])
        aapl_bar = bars.get(self.symbols["AAPL"])

        previous_spy_close = self.previous_spy_close
        previous_spy_average = self.previous_spy_average
        current_spy_average = None
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.Close))
            if len(self.spy_closes) == self.SPY_MA_PERIOD:
                current_spy_average = sum(self.spy_closes) / self.SPY_MA_PERIOD
            self.previous_spy_close = float(spy_bar.Close)
            self.previous_spy_average = current_spy_average

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)
            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        # A missing bar for any subscription suppresses every rule for the day.
        if any(symbol not in bars for symbol in self.symbols.values()):
            return

        self._run_spy_strategy(
            float(spy_bar.Close),
            previous_spy_close,
            current_spy_average,
            previous_spy_average,
        )
        self._run_aapl_strategy(float(aapl_bar.Close))

    def _run_spy_strategy(
        self, close, previous_close, current_average, previous_average
    ):
        if (
            previous_close is None
            or previous_average is None
            or current_average is None
        ):
            return

        crossed_below = (
            previous_close >= previous_average and close < current_average
        )
        crossed_above = (
            previous_close <= previous_average and close > current_average
        )

        # Sells are evaluated before buys, and only for this strategy's lot.
        if self.spy_lot > 0:
            if crossed_below:
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0
            return

        if crossed_above:
            quantity = floor(
                0.40 * float(self.Portfolio.TotalPortfolioValue) / close
            )
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

    def _run_aapl_strategy(self, close):
        # The RSI must be fully formed before either rule may trade.
        if not self.aapl_rsi.IsReady:
            return

        if self.aapl_lot > 0:
            if float(self.aapl_rsi.Current.Value) > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0
            return

        if self.aapl_red_streak >= 3:
            cash_required = 20_000
            if float(self.Portfolio.Cash) >= cash_required:
                quantity = floor(cash_required / close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

