class ParallelSpyAaplStrategies(QCAlgorithm):
    SPY_MOVING_AVERAGE_PERIOD = 20
    AAPL_RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=self.SPY_MOVING_AVERAGE_PERIOD)
        self.previous_spy_close = None
        self.previous_spy_average = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi_change_count = 0
        self.aapl_initial_gains = 0.0
        self.aapl_initial_losses = 0.0
        self.aapl_average_gain = None
        self.aapl_average_loss = None
        self.aapl_rsi = None

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_order_id = None
        self.aapl_order_id = None

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        spy_crosses_above = False
        spy_crosses_below = False
        if "SPY" in bars:
            spy_close = float(bars["SPY"].Close)
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == self.SPY_MOVING_AVERAGE_PERIOD:
                spy_average = sum(self.spy_closes) / self.SPY_MOVING_AVERAGE_PERIOD
                if self.previous_spy_average is not None:
                    spy_crosses_above = (
                        self.previous_spy_close <= self.previous_spy_average
                        and spy_close > spy_average
                    )
                    spy_crosses_below = (
                        self.previous_spy_close >= self.previous_spy_average
                        and spy_close < spy_average
                    )
                self.previous_spy_average = spy_average
            else:
                self.previous_spy_average = None
            self.previous_spy_close = spy_close

        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].Close)
            if self.previous_aapl_close is not None:
                change = aapl_close - self.previous_aapl_close
                if change < 0:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

                gain = max(change, 0.0)
                loss = max(-change, 0.0)
                if self.aapl_rsi_change_count < self.AAPL_RSI_PERIOD:
                    self.aapl_initial_gains += gain
                    self.aapl_initial_losses += loss
                    self.aapl_rsi_change_count += 1
                    if self.aapl_rsi_change_count == self.AAPL_RSI_PERIOD:
                        self.aapl_average_gain = (
                            self.aapl_initial_gains / self.AAPL_RSI_PERIOD
                        )
                        self.aapl_average_loss = (
                            self.aapl_initial_losses / self.AAPL_RSI_PERIOD
                        )
                        self.aapl_rsi = self._rsi(
                            self.aapl_average_gain, self.aapl_average_loss
                        )
                else:
                    self.aapl_average_gain = (
                        self.aapl_average_gain * (self.AAPL_RSI_PERIOD - 1) + gain
                    ) / self.AAPL_RSI_PERIOD
                    self.aapl_average_loss = (
                        self.aapl_average_loss * (self.AAPL_RSI_PERIOD - 1) + loss
                    ) / self.AAPL_RSI_PERIOD
                    self.aapl_rsi = self._rsi(
                        self.aapl_average_gain, self.aapl_average_loss
                    )
            self.previous_aapl_close = aapl_close

        if len(bars) != len(self.symbols):
            return

        # All sell rules are evaluated before either strategy's buy rule.
        if (
            self.spy_lot > 0
            and self.spy_order_id is None
            and spy_crosses_below
        ):
            ticket = self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
            self.spy_order_id = ticket.OrderId

        if (
            self.aapl_lot > 0
            and self.aapl_order_id is None
            and self.aapl_rsi is not None
            and self.aapl_rsi > 60
        ):
            ticket = self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_order_id = ticket.OrderId

        if (
            self.spy_lot == 0
            and self.spy_order_id is None
            and spy_crosses_above
        ):
            close = float(bars["SPY"].Close)
            quantity = floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / close)
            if quantity > 0:
                ticket = self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_order_id = ticket.OrderId

        if (
            self.aapl_lot == 0
            and self.aapl_order_id is None
            and self.aapl_red_streak >= 3
            and float(self.Portfolio.Cash) >= 20_000
        ):
            close = float(bars["AAPL"].Close)
            quantity = floor(20_000 / close)
            if quantity > 0:
                ticket = self.MarketOrder(self.symbols["AAPL"], quantity)
                self.aapl_order_id = ticket.OrderId

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            fill_quantity = int(order_event.FillQuantity)
            if order_event.OrderId == self.spy_order_id:
                self.spy_lot += fill_quantity
            elif order_event.OrderId == self.aapl_order_id:
                self.aapl_lot += fill_quantity

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            if order_event.OrderId == self.spy_order_id:
                self.spy_order_id = None
            elif order_event.OrderId == self.aapl_order_id:
                self.aapl_order_id = None

    @staticmethod
    def _rsi(average_gain, average_loss):
        if average_loss == 0:
            return 100.0 if average_gain > 0 else 50.0
        return 100.0 - 100.0 / (1.0 + average_gain / average_loss)

from AlgorithmImports import *
from collections import deque
from math import floor


class IndependentSpyAaplStrategies(QCAlgorithm):
    MOVING_AVERAGE_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=self.MOVING_AVERAGE_PERIOD)
        self.spy_previous_close = None
        self.spy_previous_average = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        spy = bars.get("SPY")
        spy_close = None
        spy_average = None
        spy_ready = False
        if spy is not None:
            spy_close = float(spy.Close)
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == self.MOVING_AVERAGE_PERIOD:
                spy_average = sum(self.spy_closes) / self.MOVING_AVERAGE_PERIOD
                spy_ready = (
                    self.spy_previous_close is not None
                    and self.spy_previous_average is not None
                )

        aapl = bars.get("AAPL")
        aapl_close = None
        if aapl is not None:
            aapl_close = float(aapl.Close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl.EndTime, aapl.Close)

        complete_day = len(bars) == len(self.symbols)
        if complete_day:
            # Sells are evaluated before buys.
            if (
                self.spy_lot > 0
                and spy_ready
                and self.spy_previous_close >= self.spy_previous_average
                and spy_close < spy_average
            ):
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0

            if (
                self.aapl_lot > 0
                and self.aapl_rsi.IsReady
                and float(self.aapl_rsi.Current.Value) > 60
            ):
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0

            if (
                self.spy_lot == 0
                and spy_ready
                and self.spy_previous_close <= self.spy_previous_average
                and spy_close > spy_average
            ):
                quantity = floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / spy_close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["SPY"], quantity)
                    self.spy_lot = quantity

            if (
                self.aapl_lot == 0
                and self.aapl_rsi.IsReady
                and self.aapl_red_streak >= 3
                and float(self.Portfolio.Cash) >= 20_000
            ):
                quantity = floor(20_000 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

        if spy is not None:
            self.spy_previous_close = spy_close
            if spy_average is not None:
                self.spy_previous_average = spy_average
        if aapl is not None:
            self.aapl_previous_close = aapl_close

from AlgorithmImports import *
from math import floor


class IndependentSpyAaplStrategies(QCAlgorithm):
    MOVING_AVERAGE_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            security = self.AddEquity(ticker, Resolution.Daily)
            self.symbols[ticker] = security.Symbol

        self.spy_sma = SimpleMovingAverage(self.MOVING_AVERAGE_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_previous_close = None
        self.spy_previous_sma = None
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        bars = data.Bars
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        spy_bar = bars[spy] if bars.ContainsKey(spy) else None
        aapl_bar = bars[aapl] if bars.ContainsKey(aapl) else None

        if spy_bar is not None:
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

        if aapl_bar is not None:
            if self.aapl_previous_close is not None:
                if aapl_bar.Close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        all_bars_present = all(
            bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )
        indicators_ready = (
            self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and self.spy_previous_close is not None
            and self.spy_previous_sma is not None
            and self.aapl_previous_close is not None
        )

        if all_bars_present and indicators_ready:
            spy_close = spy_bar.Close
            spy_sma = self.spy_sma.Current.Value

            # Sells are evaluated before buys.
            if (
                self.spy_lot > 0
                and self.spy_previous_close >= self.spy_previous_sma
                and spy_close < spy_sma
            ):
                self.MarketOrder(spy, -self.spy_lot)
                self.spy_lot = 0

            if self.aapl_lot > 0 and self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(aapl, -self.aapl_lot)
                self.aapl_lot = 0

            if (
                self.spy_lot == 0
                and self.spy_previous_close <= self.spy_previous_sma
                and spy_close > spy_sma
            ):
                quantity = floor(
                    0.40 * self.Portfolio.TotalPortfolioValue / spy_close
                )
                if quantity > 0:
                    self.MarketOrder(spy, quantity)
                    self.spy_lot = quantity

            if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
                allocation = 20_000
                if self.Portfolio.Cash >= allocation:
                    quantity = floor(allocation / aapl_bar.Close)
                    if quantity > 0:
                        self.MarketOrder(aapl, quantity)
                        self.aapl_lot = quantity

        if spy_bar is not None:
            self.spy_previous_close = spy_bar.Close
            if self.spy_sma.IsReady:
                self.spy_previous_sma = self.spy_sma.Current.Value

        if aapl_bar is not None:
            self.aapl_previous_close = aapl_bar.Close
